    updateReservesV2(reserves, amount0, amount1) {

        const reserve0New = reserves[0].plus(amount0);
        const reserve1New = reserves[1].plus(amount1);
        const priceToken0InToken1 = reserve1New.div(reserve0New); // token1 per token0
        const priceToken1InToken0 = reserve0New.div(reserve1New); // token0 per token1

        // Log it
   
        return [reserve0New, reserve1New];
    }
    updateReservesV3(sqrtPriceX96, liquidity, amount0, amount1) {
        const Q96 = new BigNumber(2).pow(96);
        this.sqrtPriceX96 = sqrtPriceX96
        this.liquidity = liquidity
        // Convert sqrtPriceX96 → actual price
        // Calculate virtual reserves from liquidity
        const reserve0 = new BigNumber(liquidity).times(Q96).div(sqrtPriceX96);
        const reserve1 = new BigNumber(liquidity).times(sqrtPriceX96).div(Q96);

        // Apply swap changes
        const newReserve0 = reserve0.plus(amount0);
        const newReserve1 = reserve1.plus(amount1);

        // Recompute new sqrtPriceX96
        const newPrice = newReserve1.div(newReserve0);
        const newSqrtPriceX96 = newPrice.sqrt().times(Q96);

        // Compute new liquidity (approximation: same if no tick change)
        const newLiquidity = liquidity; // unless your swap crosses tick boundaries

 

        return [newSqrtPriceX96, newLiquidity];
    }
    async getReserves() {

        if (this.version == 0 || this.version == 2 || this.version == 4) {
            const poolContract = new ethers.Contract(this.pool, Simulator.UniV2PoolAbi, this.provider);
            const reserses = await poolContract.getReserves();
            return [new BigNumber(reserses[0]), new BigNumber(reserses[1])];
        }
        else if (this.version == 1 || this.version == 3 || this.version == 5) {
            const poolContract = new ethers.Contract(this.pool, (this.version == 1 || this.version == 5) ? Simulator.UniV3PoolAbi : Simulator.AeroV3PoolAbi, this.provider);
            const slot0 = await poolContract.slot0();
            const sqrtPriceX96 = new BigNumber(slot0[0].toString())
            this.sqrtPriceX96 = sqrtPriceX96;
            const liquidity = await poolContract.liquidity()
            this.liquidity = liquidity;
            const Bliquidity = new BigNumber(liquidity.toString())
            const Q96 = new BigNumber(2).pow(96);
            const sqrtPrice = new BigNumber(sqrtPriceX96.toString());
            const reserve0 = Bliquidity.times(Q96).div(sqrtPrice);
            const reserve1 = Bliquidity.times(sqrtPrice).div(Q96);
            return [0n, 0n]
        }
    }

